-- Join Lowest Server: scan up to 50 pages (excludeFullGames), sort by player count, spread across the emptiest
-- tier so repeated hops don't all pile into the same server, then teleport with a fall-through retry chain.
local spawnerHopping = false
local function hopLowest()
    if spawnerHopping then return end
    spawnerHopping = true
    setStatus("กำลังสแกนเซิร์ฟเวอร์...")
    task.spawn(function()
        local HttpService = game:GetService("HttpService")
        local placeId = game.PlaceId
        local function httpGetJson(url)
            local body
            local req = (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request) or http_request or request or (getgenv and getgenv().request)
            if req then local ok, res = pcall(req, { Url = url, Method = "GET" }); if ok and type(res) == "table" then body = res.Body or res.body end end
            if not body or body == "" then local ok, res = pcall(function() return game:HttpGet(url) end); if ok then body = res end end
            if not body or body == "" then return nil end
            local ok, data = pcall(function() return HttpService:JSONDecode(body) end); if ok then return data end
        end
        local list, cursor = {}, nil
        for _ = 1, 50 do
            local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100"):format(placeId)
            if cursor then url = url .. "&cursor=" .. cursor end
            local data = httpGetJson(url)
            if not data or type(data.data) ~= "table" then break end
            for _, s in ipairs(data.data) do
                if type(s.playing) == "number" and s.id ~= game.JobId and s.playing < (s.maxPlayers or 999) then list[#list + 1] = s end
            end
            table.sort(list, function(a, b) return a.playing < b.playing end)
            if #list >= 40 and list[1].playing <= 2 then break end
            if data.nextPageCursor and data.nextPageCursor ~= "" then cursor = data.nextPageCursor else break end
            task.wait(0.12)
        end
        if #list == 0 then setStatus("ไม่มีเซิร์ฟเวอร์ให้เข้า (API ถูกบล็อกหรือเต็มทั้งหมด) - ลองใหม่"); spawnerHopping = false; return end
        table.sort(list, function(a, b) return a.playing < b.playing end)
        local minP, pool = list[1].playing, {}
        for _, s in ipairs(list) do if s.playing <= minP + 1 then pool[#pool + 1] = s end end
        if #pool < 3 then for i = 1, math.min(8, #list) do pool[i] = list[i] end end
        for i = #pool, 2, -1 do local j = math.random(1, i); pool[i], pool[j] = pool[j], pool[i] end
        local order = {}
        for _, s in ipairs(pool) do order[#order + 1] = s end
        for _, s in ipairs(list) do order[#order + 1] = s end
        setStatus(("กำลังย้าย -> ว่างสุด %d (%d เซิร์ฟเวอร์)"):format(minP, #list))
        local idx, conn = 0, nil
        local function tryNext()
            idx = idx + 1
            local s = order[idx]
            if not s then if conn then conn:Disconnect() end; spawnerHopping = false; setStatus("ย้ายล้มเหลวทั้งหมด - ลองใหม่"); return end
            pcall(function() TeleportService:TeleportToPlaceInstance(placeId, s.id, lp) end)
        end
        conn = TeleportService.TeleportInitFailed:Connect(function(who) if who == lp then task.wait(0.6); tryNext() end end)
        tryNext()
        task.delay(30, function() if conn then conn:Disconnect() end; spawnerHopping = false end)
    end)
end
